    for root in roots:
        depth_first(root)
    skip = {}

    def keep(name):
        return quotas[name]['capacity'] < bound.get(name, 0)

    resolved = {}

    def effective(name):
        found = resolved.get(name, False)
        if found is not False:
            return found
        chain = []
        walk = name
        while walk is not None and not keep(walk):
            chain.append(walk)
            parent = quotas[walk]['parent']
            walk = parent if parent in paths else None
        answer = walk
        for item in chain:
            resolved[item] = answer
        return answer

    edges = {}
